#!/usr/bin/env node

/*
 * Move old log files into an archive directory and record a manifest.
 * Usage: node scripts/archive-logs.mjs --before YYYY-MM-DD [--dir logs]
 */
import { promises as fs } from 'fs';
import path from 'path';
import { fileURLToPath, pathToFileURL } from 'url';

const argv = process.argv.slice(2);
let beforeDateStr;
let dir = 'logs';
for (let i = 0; i < argv.length; i++) {
  const arg = argv[i];
  if (arg === '--before' && i + 1 < argv.length) {
    beforeDateStr = argv[i + 1];
    i++;
  } else if (arg === '--dir' && i + 1 < argv.length) {
    dir = argv[i + 1];
    i++;
  }
}

function isValidYYYYMMDD(str) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(str)) return false;
  const date = new Date(str + 'T00:00:00Z');
  return date instanceof Date && !isNaN(date) && date.toISOString().slice(0, 10) === str;
}

if (!beforeDateStr || !isValidYYYYMMDD(beforeDateStr)) {
  process.exit(2);
}
const beforeDate = new Date(beforeDateStr + 'T00:00:00Z');
const baseDir = path.resolve(dir);
const archiveBase = path.join(baseDir, 'archive');

async function main() {
  const files = await fs.readdir(baseDir, { withFileTypes: true });
  const moved = [];
  for (const dirent of files) {
    if (!dirent.isFile()) continue;
    const name = dirent.name;
    const match = name.match(/^app-(\d{4}-\d{2}-\d{2})\.log$/);
    if (!match) continue;
    const fileDateStr = match[1];
    const fileDate = new Date(fileDateStr + 'T00:00:00Z');
    if (fileDate < beforeDate) {
      const monthDir = `${fileDate.getFullYear()}-${String(fileDate.getMonth() + 1).padStart(2, '0')}`;
      const targetDir = path.join(archiveBase, monthDir);
      await fs.mkdir(targetDir, { recursive: true });
      const src = path.join(baseDir, name);
      const dest = path.join(targetDir, name);
      await fs.rename(src, dest);
      moved.push({ file: name, to: path.relative(baseDir, dest).replace(/\\/g, '/') });
    }
  }
  if (moved.length > 0) {
    const manifestPath = path.join(archiveBase, 'manifest.json');
    let existing = [];
    try {
      const data = await fs.readFile(manifestPath, 'utf8');
      const obj = JSON.parse(data);
      existing = obj.moved || [];
    } catch (_) {}
    const combined = existing.concat(moved.map(e => ({ file: e.file, to: e.to })));
    await fs.writeFile(manifestPath, JSON.stringify({ moved: combined }, null, 2));
  }
}

main().catch(err => {
  console.error(err);
  process.exit(1);
});

