#!/usr/bin/env node
import path from 'node:path';
import os from 'node:os';
import { pathToFileURL } from 'node:url';
import { openStore } from './store.mjs';
import { filterTasks, sortTasks, paginate } from './query.mjs';
import { formatList } from './format.mjs';

const VALUE_FLAGS = new Set(['priority', 'due', 'tag', 'status', 'sort', 'page', 'size', 'notes', 'file', 'search']);
const BOOLEAN_FLAGS = new Set(['overdue', 'help']);

// Supports --flag value, --flag=value, and boolean --flag. "--" ends options.
export function parseArgs(argv) {
  const positional = [];
  const flags = {};
  const tags = [];
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '--') { positional.push(...argv.slice(i + 1)); break; }
    if (!arg.startsWith('--')) { positional.push(arg); continue; }
    const eq = arg.indexOf('=');
    const name = eq === -1 ? arg.slice(2) : arg.slice(2, eq);
    if (BOOLEAN_FLAGS.has(name)) {
      if (eq !== -1) throw new Error(`--${name} does not take a value`);
      flags[name] = true;
      continue;
    }
    if (!VALUE_FLAGS.has(name)) throw new Error(`Unknown option: --${name}`);
    let value;
    if (eq !== -1) value = arg.slice(eq + 1);
    else {
      value = argv[++i];
      if (value === undefined) throw new Error(`--${name} needs a value`);
    }
    if (name === 'tag') tags.push(value);
    else flags[name] = value;
  }
  if (tags.length) flags.tags = tags;
  return { command: positional[0], args: positional.slice(1), flags };
}

function parseId(text) {
  if (!/^[1-9]\d*$/.test(String(text))) throw new Error(`Invalid task ID: ${text}`);
  return Number(text);
}

export async function run(argv, { stdout = process.stdout, env = process.env, now } = {}) {
  const { command, args, flags } = parseArgs(argv);
  const file = flags.file || env.TASKFLOW_FILE || path.join(os.homedir(), '.taskflow.json');
  const store = await openStore(file, now ? { now } : {});
  const print = (text) => stdout.write(text + '\n');
  const clock = now ? now() : new Date();
  switch (command) {
    case 'add': {
      const task = await store.add({ title: args.join(' '), priority: flags.priority, due: flags.due, tags: flags.tags, notes: flags.notes });
      print(`Added task ${task.id}.`);
      return 0;
    }
    case 'list': {
      const filtered = filterTasks(store.all(), { status: flags.status || 'open', tag: flags.tags && flags.tags[0], priority: flags.priority, overdue: flags.overdue, search: flags.search, now: clock });
      const sorted = sortTasks(filtered, flags.sort || 'id');
      const page = paginate(sorted, flags.page ? Number(flags.page) : 1, flags.size ? Number(flags.size) : 20);
      print(formatList(page.items, { now: clock }));
      if (page.pages > 1) print(`Page ${page.page} of ${page.pages} (${page.total} tasks)`);
      return 0;
    }
    case 'done': {
      for (const id of args.map(parseId)) await store.update(id, { status: 'done' });
      print(`Completed ${args.length} task(s).`);
      return 0;
    }
    case 'reopen': {
      for (const id of args.map(parseId)) await store.update(id, { status: 'open' });
      print(`Reopened ${args.length} task(s).`);
      return 0;
    }
    case 'tag': {
      const [id, ...tagList] = args;
      await store.update(parseId(id), { addTags: tagList });
      print(`Tagged task ${id}.`);
      return 0;
    }
    case 'rm': {
      for (const id of args.map(parseId)) await store.remove(id);
      print(`Removed ${args.length} task(s).`);
      return 0;
    }
    default:
      print('Usage: taskflow <add|list|done|reopen|tag|rm> [options]');
      return command ? 2 : 0;
  }
}

if (import.meta.url === pathToFileURL(process.argv[1] || '').href) {
  run(process.argv.slice(2)).then((code) => { process.exitCode = code; }, (error) => {
    process.stderr.write(`taskflow: ${error.message}\n`);
    process.exitCode = 1;
  });
}

import { isOverdue } from './dates.mjs';
import { PRIORITIES, normalizeTag } from './task.mjs';

export function filterTasks(tasks, { status, tag, priority, overdue, search, now = new Date() } = {}) {
  const wanted = tag ? normalizeTag(tag) : null;
  return tasks.filter((task) => {
    if (status && status !== 'all' && task.status !== status) return false;
    if (wanted && !task.tags.includes(wanted)) return false;
    if (priority && task.priority !== priority) return false;
    if (overdue && !isOverdue(task, now)) return false;
    if (search) {
      const s = search.trim().toLowerCase();
      if (s && !((task.title.toLowerCase().includes(s)) || (task.notes && task.notes.toLowerCase().includes(s)))) return false;
    }
    return true;
  });
}

const SORTERS = {
  id: (a, b) => a.id - b.id,
  due: (a, b) => (a.due === b.due ? 0 : a.due === null ? 1 : b.due === null ? -1 : a.due < b.due ? -1 : 1),
  priority: (a, b) => PRIORITIES.indexOf(b.priority) - PRIORITIES.indexOf(a.priority),
  title: (a, b) => a.title.localeCompare(b.title)
};

// Stable sort; ties keep ID order.
export function sortTasks(tasks, key = 'id') {
  const compare = SORTERS[key];
  if (!compare) throw new Error(`Unknown sort key: ${key}`);
  return [...tasks].sort((a, b) => compare(a, b) || a.id - b.id);
}

// Pages are numbered from 1.
export function paginate(items, page = 1, size = 20) {
  if (!Number.isInteger(page) || page < 1) throw new Error('Page must be a positive integer');
  if (!Number.isInteger(size) || size < 1 || size > 100) throw new Error('Page size must be between 1 and 100');
  const start = (page - 1) * size;
  return { items: items.slice(start, start + size), page, pages: Math.max(1, Math.ceil(items.length / size)), total: items.length };
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { filterTasks, sortTasks, paginate } from '../src/query.mjs';
import { NOW } from './helpers.mjs';

const tasks = [
  { id: 1, title: 'b', priority: 'low', status: 'open', due: '2026-11-05', tags: ['home'] },
  { id: 2, title: 'a', priority: 'high', status: 'done', due: null, tags: ['work'] },
  { id: 3, title: 'c', priority: 'normal', status: 'open', due: '2026-10-30', tags: ['work'] },
  { id: 4, title: 'd', priority: 'high', status: 'open', due: '2026-11-02', tags: [] }
];

test('filters by status, tag, priority and overdue', () => {
  assert.deepEqual(filterTasks(tasks, { status: 'open' }).map((t) => t.id), [1, 3, 4]);
  assert.deepEqual(filterTasks(tasks, { status: 'all', tag: 'work' }).map((t) => t.id), [2, 3]);
  assert.deepEqual(filterTasks(tasks, { priority: 'high' }).map((t) => t.id), [2, 4]);
  assert.deepEqual(filterTasks(tasks, { overdue: true, now: NOW }).map((t) => t.id), [3]);
});

test('sorts by due date with undated tasks last, and by priority', () => {
  assert.deepEqual(sortTasks(tasks, 'due').map((t) => t.id), [3, 4, 1, 2]);
  assert.deepEqual(sortTasks(tasks, 'priority').map((t) => t.id), [2, 4, 3, 1]);
  assert.throws(() => sortTasks(tasks, 'color'), /Unknown sort key/);
});

test('paginates from page 1', () => {
  const items = Array.from({ length: 5 }, (_, i) => i);
  assert.deepEqual(paginate(items, 1, 2), { items: [0, 1], page: 1, pages: 3, total: 5 });
  assert.deepEqual(paginate(items, 3, 2).items, [4]);
  assert.throws(() => paginate(items, 0, 2), /positive integer/);
});

 test('search matches title and notes', () => {
   const tasks = [
     { id: 1, title: 'First task', notes: 'Some notes', tags: [], priority: 'low', status: 'open', due: null },
     { id: 2, title: 'Second Task', notes: '', tags: [], priority: 'high', status: 'open', due: null },
     { id: 3, title: 'Another', notes: 'Different', tags: [], priority: 'normal', status: 'open', due: null }
   ];
   assert.deepEqual(filterTasks(tasks, { search: 'second' }).map(t=>t.id), [2]);
   assert.deepEqual(filterTasks(tasks, { search: 'task' }).map(t=>t.id), [1,2]);
   assert.deepEqual(filterTasks(tasks, { search: 'notes' }).map(t=>t.id), [1]);
   assert.deepEqual(filterTasks(tasks, { search: '  ' }).map(t=>t.id), [1,2,3]);
 });
